#include <iostream>

struct Bullet
{
    inline static int alive = 0;
    int damage;
    Bullet(int damage) : damage(damage) { alive++; }
    ~Bullet() { alive--; }
};

int main()
{
    Bullet* b = new Bullet(10);
    std::cout << "alive: " << Bullet::alive << ", damage " << b->damage << "\n";
    delete b;
    b = nullptr;
    std::cout << "alive after delete: " << Bullet::alive << "\n";

    int n = 5;
    int* samples = new int[n];
    for (int i = 0; i < n; i++) samples[i] = i * i;
    std::cout << "last sample " << samples[n - 1] << "\n";
    delete[] samples;              // new[] pairs with delete[]
    return 0;
}

