int* makeReadings(int count, int start)
{
    if (count <= 0) return nullptr;
    int* p = new int[count];        // the caller now owns this array
    for (int i = 0; i < count; i++) p[i] = start + i;
    return p;
}

void freeReadings(int* readings)
{
    delete[] readings;              // new[] pairs with delete[]; nullptr is fine
}

