int* grow(int* old, int oldSize, int newSize)
{
    int* bigger = new int[newSize];
    for (int i = 0; i < newSize; i++)
        bigger[i] = (i < oldSize) ? old[i] : 0;
    delete[] old;          // the old array is ours to release
    return bigger;
}

