exercises.solution:
struct Bullet
{
    inline static int alive = 0;   // how many Bullets exist right now
    int damage;
    Bullet(int damage) : damage(damage) { alive++; }
    ~Bullet() { alive--; }           // runs when a Bullet is destroyed (unit 4 explains)
};

Bullet* spawnBullet(int damage)
{
    return new Bullet(damage);   // the caller owns it now
}

void despawn(Bullet*& b)
{
    delete b;        // safe on nullptr
    b = nullptr;     // the caller's pointer can't dangle
}
